begin;
with j as (select * from jsonb_to_recordset($law7d0014$[{"code_id":"APK_RF","article_number":"260","version_date":"2002-07-24","article_text":"1. Апелляционная жалоба может быть подана в арбитражный суд на бумажном носителе или в электронном виде, в том числе в форме электронного документа. Апелляционная жалоба подписывается лицом, подающим жалобу, или его представителем, уполномоченным на подписание жалобы.\n\nАпелляционная жалоба, подаваемая в электронном виде, содержащая ходатайство об обеспечении иска, должна быть подписана усиленной квалифицированной электронной подписью.\n\n(Часть в редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В апелляционной жалобе должны быть указаны:\n\n1) наименование арбитражного суда, в который подается апелляционная жалоба;\n\n2) наименование лица, подающего жалобу, и других лиц, участвующих в деле;\n\n3) наименование арбитражного суда, принявшего обжалуемое решение, номер дела и дата принятия решения, предмет спора;\n\n4) требования лица, подающего жалобу, и основания, по которым лицо, подающее жалобу, обжалует решение, со ссылкой на законы, иные нормативные правовые акты, обстоятельства дела и имеющиеся в деле доказательства;\n\n5) перечень прилагаемых к жалобе документов.\n\nВ апелляционной жалобе могут быть указаны номера телефонов, факсов, адреса электронной почты и иные необходимые для рассмотрения дела сведения, а также заявлены имеющиеся ходатайства.\n\n3. Лицо, подающее апелляционную жалобу, обязано направить другим лицам, участвующим в деле, копии апелляционн\n\nой жалобы и прилагаемых к ней документов, которые у них отсутствуют, заказным письмом с уведомлением о вручении либо вручить их другим лицам, участвующим в деле, или их представителям лично под расписку.\n\nАпелляционная жалоба и прилагаемые к ней документы в электронном виде направляются лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n4. К апелляционной жалобе прилагаются:\n\n1) копия оспариваемого решения;\n\n2) документы, подтверждающие уплату государственной пошлины в установленных порядке и размере или право на получение льготы по уплате государственной пошлины, либо ходатайство о предоставлении отсрочки, рассрочки ее уплаты или об уменьшении размера государственной пошлины;\n\n3) документ, подтверждающий направление или вручение другим лицам, участвующим в деле, копий апелляционной жалобы и документов, которые у них отсутствуют;\n\n4) доверенность или иной документ, подтверждающие полномочия на подписание апелляционной жалобы, а также копии документов о высшем юридическом образовании или об ученой степени по юридической специальности представителя, подписавшего апелляционную жалобу, либо документов, удостоверяющих его статус адвоката, патентного поверенного, арбитражного управляющего, единоличного органа управления организации. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\nК апелляционной жалобе на определение арбитражного суда о возвращении искового заявления должны быть также приложены возвращенное исковое заявление и документы, прилагавшиеся к нему при подаче в арбитражный суд. Документы, прилагаемые к апелляционной жалобе, могут быть представлены в арбитражный суд в электронном виде. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 260. Форма и содержание апелляционной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a49b8b70d002d355c4f8cde4ea0ebc463d2601f2017d1c363e0143885020c3c"},{"code_id":"APK_RF","article_number":"261","version_date":"2002-07-24","article_text":"1. Апелляционная жалоба, поданная с соблюдением требований, предъявляемых настоящим Кодексом к ее форме и содержанию, принимается к производству арбитражного суда апелляционной инстанции. В случае нарушения указанных требований арбитражный суд или оставляет жалобу без движения, или возвращает ее в порядке, предусмотренном в статьях 263 и 264 настоящего Кодекса.\n\n2. Вопрос о принятии апелляционной жалобы к производству решается судьей арбитражного суда апелляционной инстанции единолично в пятидневный срок со дня ее поступления в арбитражный суд апелляционной инстанции.\n\nО принятии апелляционной жалобы арбитражный суд апелляционной инстанции выносит определение, которым возбуждается производство по апелляционной жалобе.\n\nВ определении указываются время и место проведения судебного заседания по рассмотрению апелляционной жалобы. При этом время проведения первого судебного заседания по рассмотрению апелляционной жалобы определяется с учетом того, что оно не может быть назначено ранее истечения срока, установленного настоящим Кодексом для обжалования соответствующего решения арбитражного суда. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 261. Принятие апелляционной жалобы к производству арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c69256f7cf481c94f78b243c28ba5c03fa7e133bc931a788de20ebd7ed19648"},{"code_id":"APK_RF","article_number":"262","version_date":"2002-07-24","article_text":"1. Лицо, участвующее в деле, направляет отзыв на апелляционную жалобу с приложением документов, подтверждающих возражения относительно жалобы, другим лицам, участвующим в деле, и в арбитражный суд.\n\nК отзыву, направляемому в арбитражный суд, прилагается также документ, подтверждающий направление отзыва другим лицам, участвующим в деле.","article_title":"Статья 262. Отзыв на апелляционную жалобу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a6ed791d69b5321994d73cfb1894535b2bf83aab45a02a9e999800cf0a21b8ce"},{"code_id":"APK_RF","article_number":"263","version_date":"2002-07-24","article_text":"1. Арбитражный суд апелляционной инстанции, установив при рассмотрении вопроса о принятии апелляционной жалобы к производству, что она подана с нарушением требований, установленных статьей 260 настоящего Кодекса, выносит определение об оставлении апелляционной жалобы без движения.\n\nАбзац. (Утратил силу - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n2. В определении арбитражный суд указывает основания для оставления апелляционной жалобы без движения и срок, в течение которого лицо, подавшее апелляционную жалобу, должно устранить обстоятельства, послужившие основанием для оставления апелляционной жалобы без движения.\n\n3. Копия определения об оставлении апелляционной жалобы без движения направляется лицу, подавшему апелляционную жалобу, не позднее следующего дня после дня его вынесения.\n\n4. В случае, если обстоятельства, послужившие основанием для оставления апелляционной жалобы без движения, будут устранены в срок, указанный в определении суда, апелляционная жалоба считается поданной в день ее первоначального поступления в суд и принимается к производству арбитражного суда апелляционной инстанции.\n\n5. В случае, если указанные обстоятельства не будут устранены в срок, указанный в определении, арбитражный суд возвращает апелляционную жалобу и прилагаемые к ней документы лицу, подавшему жалобу, в порядке, установленном статьей 264 настоящего Кодекса.","article_title":"Статья 263. Оставление апелляционной жалобы без движения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c561e425eeb0b46389a46be9d644edd03ae2cdbf1e5b38f8c652bcc8a0c4dc6"},{"code_id":"APK_RF","article_number":"264","version_date":"2002-07-24","article_text":"1. Арбитражный суд апелляционной инстанции возвращает апелляционную жалобу, если при рассмотрении вопроса о принятии апелляционной жалобы к производству установит, что:\n\n1) апелляционная жалоба подана лицом, не имеющим права на обжалование судебного акта в порядке апелляционного производства;\n\n11) апелляционная жалоба не подписана или апелляционная жалоба подписана  лицом, не имеющим полномочий на ее подписание; (Дополнение пунктом - Федеральный закон от 28.11.2018 № 451-ФЗ) (В редакции Федерального закона от 02.12.2019 № 406-ФЗ)\n\n2) апелляционная жалоба подана на судебный акт, который в соответствии с настоящим Кодексом не обжалуется в порядке апелляционного производства;\n\n3) апелляционная жалоба подана по истечении срока подачи апелляционной жалобы, установленного в настоящем Кодексе, и не содержит ходатайство о его восстановлении или в восстановлении пропущенного срока на подачу апелляционной жалобы отказано;\n\n4) до вынесения определения о принятии апелляционной жалобы к производству суда от лица, подавшего жалобу, поступило ходатайство о ее возвращении;\n\n5) не устранены обстоятельства, послужившие основанием для оставления жалобы без движения, в срок, установленный в определении суда.\n\nАрбитражный суд апелляционной инстанции также возвращает жалобу, если отклонено ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины или об уменьшении ее размера.\n\n2. О возвращении апелляционной жалобы арбитражный суд выносит определение.\n\n3. В определении указываются основания для возвращения апелляционной жалобы, решается вопрос о возврате государственной пошлины из федерального бюджета.\n\nКопия определения о возвращении апелляционной жалобы направляется лицу, подавшему жалобу, вместе с жалобой и прилагаемыми документами не позднее следующего дня после дня его вынесения или после истечения срока, установленного судом для устранения обстоятельств, послуживших основанием для оставления апелляционной жалобы без движения.\n\n4. Определение арбитражного суда о возвращении апелляционной жалобы может быть обжаловано.\n\nВ случае отмены определения апелляционная жалоба считается поданной в день первоначального обращения в арбитражный суд.\n\n5. Возвращение апелляционной жалобы не препятствует повторному обращению с апелляционной жалобой в арбитражный суд в общем порядке после устранения обстоятельств, послуживших основанием для ее возвращения.","article_title":"Статья 264. Возвращение апелляционной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bdd3aa9798701d56aab9d107dd33a54639707b68dc4d2aa2f8888cfd1bbcbd27"},{"code_id":"APK_RF","article_number":"265","version_date":"2002-07-24","article_text":"1. Арбитражный суд апелляционной инстанции прекращает производство по апелляционной жалобе, если от лица, ее подавшего, после принятия апелляционной жалобы к производству арбитражного суда поступило ходатайство об отказе от апелляционной жалобы и отказ был принят арбитражным судом в соответствии со статьей 49 настоящего Кодекса.\n\n2. В случае, если в апелляционной жалобе заявлены новые требования, которые не были предметом рассмотрения в арбитражном суде первой инстанции, принявшем обжалуемое решение, арбитражный суд апелляционной инстанции прекращает производство по апелляционной жалобе в части этих требований.\n\n3. О прекращении производства по апелляционной жалобе арбитражный суд выносит определение.\n\nКопии определения о прекращении производства по апелляционной жалобе направляются лицам, участвующим в деле, не позднее следующего дня после дня его вынесения.\n\n4. Определение арбитражного суда о прекращении производства по апелляционной жалобе может быть обжаловано.\n\n5. В случае прекращения производства по апелляционной жалобе повторное обращение того же лица по тем же основаниям в арбитражный суд с апелляционной жалобой не допускается.","article_title":"Статья 265. Прекращение производства по апелляционной жалобе","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"edbb7abf24c376eef0b5bd522c949ecc4ba9c2ea06c8282cfb8d5cfccf3b6587"},{"code_id":"APK_RF","article_number":"265.1","version_date":"2002-07-24","article_text":"1. Арбитражный суд апелляционной инстанции по ходатайству лиц, участвующих в деле, вправе приостановить исполнение судебных актов, принятых арбитражным судом первой инстанции, при условии, если заявитель обосновал невозможность или затруднительность поворота исполнения либо предоставил обеспечение, предусмотренное в части 2 настоящей статьи.\n\nХодатайство о приостановлении исполнения судебных актов, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. Исполнение решения арбитражного суда приостанавливается арбитражным судом апелляционной инстанции при предоставлении лицом, ходатайствующим о таком приостановлении, обеспечения возмещения другой стороне по делу возможных убытков (встречного обеспечения) путем внесения на депозитный счет арбитражного суда апелляционной инстанции денежных средств в размере оспариваемой суммы либо предоставления банковской гарантии, поручительства или иного финансового обеспечения на ту же сумму.\n\n3. О приостановлении исполнения судебного акта или об отказе в приостановлении исполнения арбитражный суд апелляционной инстанции выносит определение в трехдневный срок со дня поступления ходатайства в суд. Определение может быть обжаловано в арбитражный суд кассационной инстанции. Содержание этого определения может быть изложено в определении о принятии апелляционной жалобы к производству суда.\n\nКопия определения направляется лицам, участвующим в деле.\n\n4. Исполнение судебного акта приостанавливается на срок до принятия арбитражным судом апелляционной инстанции постановления по результатам рассмотрения апелляционной жалобы, если судом не установлен иной срок приостановления.\n\n(Дополнение статьей - Федеральный закон от 25.06.2012 № 86-ФЗ)","article_title":"Статья 265.1. Приостановление исполнения судебных актов арбитражным судом апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"146ba21e4ca650aefcf7cac50a0751cec3797ca857d1c774759d26aab00f0090"},{"code_id":"APK_RF","article_number":"267","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 30.04.2010 № 69-ФЗ)","article_title":"Статья 267. Срок рассмотрения апелляционной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3719fd3804ca9e264fffb5107da372c727e94e80dbaef9c4f409dfde93141e50"},{"code_id":"APK_RF","article_number":"268","version_date":"2002-07-24","article_text":"1. При рассмотрении дела в порядке апелляционного производства арбитражный суд по имеющимся в деле и дополнительно представленным доказательствам повторно рассматривает дело.\n\nДокументы, представленные для обоснования возражений относительно апелляционной жалобы в соответствии со статьей 262 настоящего Кодекса, принимаются и рассматриваются арбитражным судом апелляционной инстанции по существу.\n\nНа отмену решения арбитражного суда первой инстанции указывается в постановлении, принимаемом арбитражным судом апелляционной инстанции по результатам рассмотрения апелляционной жалобы. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n(Дополнение частью - Федеральный закон от 30.04.2010 № 69-ФЗ)","article_title":"Статья 268. Пределы рассмотрения дела арбитражным судом апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"25f4cf609512a1ec1680c9e1a0f30b96046f2c7024bb9cbccff1bdb7252b19b4"},{"code_id":"APK_RF","article_number":"269","version_date":"2002-07-24","article_text":"По результатам рассмотрения апелляционной жалобы арбитражный суд апелляционной инстанции вправе:\n\n1) оставить решение арбитражного суда первой инстанции без изменения, а апелляционную жалобу - без удовлетворения;\n\n2) отменить или изменить решение суда первой инстанции полностью или в части и принять по делу новый судебный акт;\n\n3) отменить решение полностью или в части и прекратить производство по делу либо оставить исковое заявление без рассмотрения полностью или в части.","article_title":"Статья 269. Полномочия арбитражного суда апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0bc533835f05450d62124807010094b838788e1215438d2936149a878c1772bf"},{"code_id":"APK_RF","article_number":"27","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n1) о несостоятельности (банкротстве);\n\n2) по спорам, указанным в статье 2251 настоящего Кодекса;\n\n3) по спорам об отказе в государственной регистрации, уклонении от государственной регистрации юридических лиц, индивидуальных предпринимателей;\n\n4) по спорам, вытекающим из деятельности депозитариев, связанной с учетом прав на акции и иные ценные бумаги и с осуществлением предусмотренных федеральным законом иных прав и обязанностей;\n\n5) по спорам, вытекающим из деятельности публично-правовых компаний, государственных компаний, государственных корпораций и связанным с их правовым положением, порядком управления ими, их созданием, реорганизацией, ликвидацией, организацией и с полномочиями их органов, ответственностью лиц, входящих в их органы;\n\n6) по спорам о защите интеллектуальных прав с участием организаций, осуществляющих коллективное управление авторскими и смежными правами, а также по спорам, отнесенным к подсудности Суда по интеллектуальным правам в соответствии с частью 4 статьи 34 настоящего Кодекса;\n\n7) о защите деловой репутации в сфере предпринимательской и иной экономической деятельности;\n\n71) по спорам, указанным в статье 2481 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 08.06.2020 № 171-ФЗ)\n\n8) другие дела, возникающие при осуществлении предпринимательской и иной экономической деятельности, в случаях, предусмотренных федеральным законом.\n\n(Дополнение частью - Федеральный закон от 29.12.2015 № 409-ФЗ)","article_title":"Статья 27. Споры, относящиеся к компетенции арбитражных судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"75a6172107a85f44042fe303739d3aa08eca6112946b87bd36495b2c9fa254c6"},{"code_id":"APK_RF","article_number":"270","version_date":"2002-07-24","article_text":"1. Основаниями для изменения или отмены решения арбитражного суда первой инстанции являются:\n\n1) неполное выяснение обстоятельств, имеющих значение для дела;\n\n2) недоказанность имеющих значение для дела обстоятельств, которые суд считал установленными;\n\n3) несоответствие выводов, изложенных в решении, обстоятельствам дела;\n\n4) нарушение или неправильное применение норм материального права или норм процессуального права.\n\n2. Неправильным применением норм материального права является:\n\n1) неприменение закона, подлежащего применению;\n\n2) применение закона, не подлежащего применению;\n\n3) неправильное истолкование закона.\n\n3. Нарушение или неправильное применение норм процессуального права является основанием для изменения или отмены решения арбитражного суда первой инстанции, если это нарушение привело или могло привести к принятию неправильного решения.\n\n4. Основаниями для отмены решения арбитражного суда первой инстанции в любом случае являются:\n\n1) рассмотрение дела арбитражным судом в незаконном составе;\n\n2) рассмотрение дела в отсутствие кого-либо из участвующих в деле лиц, не извещенных надлежащим образом о времени и месте судебного заседания;\n\n3) нарушение правил о языке при рассмотрении дела;\n\n4) принятие судом решения о правах и об обязан\n\nностях лиц, не привлеченных к участию в деле;\n\n5) неподписание решения судьей или одним из судей, если дело рассмотрено в коллегиальном составе судей, либо подписание решения не теми судьями, которые указаны в решении;\n\n6) отсутствие в деле протокола судебного заседания или подписание его не теми лицами, которые указаны в статье 155 настоящего Кодекса, в случае отсутствия аудиозаписи судебного заседания; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n7) нарушение правила о тайне совещания судей при принятии решения.","article_title":"Статья 270. Основания для изменения или отмены решения арбитражного суда первой инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4ced9babd807c20db39cbc9f36e634afae97159a9984c5b658c4d7957dc700b"},{"code_id":"APK_RF","article_number":"271","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения апелляционной жалобы арбитражный суд апелляционной инстанции принимает судебный акт, именуемый постановлением, которое подписывается судьями, рассматривавшими дело.\n\n2. В постановлении арбитражного суда апелляционной инстанции должны быть указаны:\n\n1) наименование арбитражного суда апелляционной инстанции, состав суда, принявшего постановление; фамилия лица, которое вело протокол судебного заседания;\n\n2) номер дела, дата и место принятия постановления;\n\n3) наименование лица, подавшего апелляционную жалобу, и его процессуальное положение;\n\n4) наименования лиц, участвующих в деле;\n\n5) предмет спора;\n\n6) фамилии лиц, присутствовавших в судебном заседании, с указанием их полномочий;\n\n7) дата принятия обжалуемого решения арбитражным судом первой инстанции; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n8) краткое изложение содержания принятого решения;\n\n9) основания, по которым в апелляционной жалобе заявлено требование о проверке законности и обоснованности решения;\n\n10) доводы, изложенные в отзыве на апелляционную жалобу;\n\n11) объяснения лиц, участвующих в деле и присутствующих в судебном заседании;\n\n12) обстоятельства дела, установленные арбитражным судом апелляционной инстанции; доказательства, на которых основаны выводы суда об этих обстоятельствах; законы и иные нормативные правовые акты, которыми руководствовался суд при принятии постановления; мотивы, по которым суд отклонил те или иные доказательства и не применил законы и иные нормативные правовые акты, на которые ссылались лица, участвующие в деле;\n\n13) мотивы, по которым суд апелляционной инстанции не согласился с выводами суда первой инстанции, если его решение было отменено полностью или в части;\n\n14) выводы о результатах рассмотрения апелляционной жалобы.\n\n3. В постановлении арбитражного суда апелляционной инстанции указывается на распределение между сторонами судебных расходов, в том числе судебных расходов, понесенных в связи с подачей апелляционной жалобы.\n\n4. Копии постановления арбитражного суда апелляционной инстанции направляются лицам, участвующим в деле, в пятидневный срок со дня принятия постановления.\n\n5. Постановление арбитражного суда апелляционной инстанции вступает в законную силу со дня его принятия.","article_title":"Статья 271. Постановление арбитражного суда апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"765c2b3fc08f85743a5837bf0feefb69c1e76cd0ce95078f1665f8383527ea7a"},{"code_id":"APK_RF","article_number":"272","version_date":"2002-07-24","article_text":"1. Определения арбитражного суда первой инстанции обжалуются в арбитражный суд апелляционной инстанции в соответствии со статьей 188 настоящего Кодекса.\n\nАпелляционные жалобы на определения арбитражного суда первой инстанции, за исключением случаев, предусмотренных настоящим Кодексом, рассматриваются судьей арбитражного суда апелляционной инстанции единолично. (Дополнение абзацем - Федеральный закон от 28.11.2018 № 451-ФЗ)\n\n1) оставить определение без изменения, жалобу без удовлетворения;\n\n2) отменить определение арбитражного суда первой инстанции и направить вопрос на новое рассмотрение в арбитражный суд первой инстанции;\n\n3) отменить определение полностью или в части и разрешить вопрос по существу.","article_title":"Статья 272. Апелляционные жалобы на определения арбитражного суда первой инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f1df7e839d3b34071457d709359a297698c97de3badca114b4cb8bb6eb3f6b28"},{"code_id":"APK_RF","article_number":"272.1","version_date":"2002-07-24","article_text":"(Дополнение статьей - Федеральный закон от 25.06.2012 № 86-ФЗ)\n\n(Наименование в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 272.1. Апелляционные жалобы на решения арбитражного суда по делам, рассмотренным в порядке упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ce764ba10aeb868bac600092ee988b5770e451adb23545ea1ce0f21eff006392"},{"code_id":"APK_RF","article_number":"273","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 273. Право кассационного обжалования","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0dcb8aa602e92c57e5152bcb95c6af95dbb96cc7240b502c878aacb65ed6813c"},{"code_id":"APK_RF","article_number":"274","version_date":"2002-07-24","article_text":"1) дела, рассмотренные им в качестве суда первой инстанции;\n\n2) дела о защите интеллектуальных прав, рассмотренные арбитражными судами субъектов Российской Федерации в качестве суда первой инстанции, арбитражными апелляционными судами.\n\n(Дополнение частью - Федеральный закон от 08.12.2011 № 422-ФЗ)","article_title":"Статья 274. Арбитражный суд кассационной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4ab952abacd7259cecec12b08b808dc821a29f63a57d24c5f256ca9f5e3bf24"},{"code_id":"APK_RF","article_number":"275","version_date":"2002-07-24","article_text":"1. Кассационная жалоба подается в арбитражный суд кассационной инстанции, полномочный ее рассматривать, через арбитражный суд, принявший решение.\n\n2. Арбитражный суд, принявший решение, обязан направить кассационную жалобу вместе с делом в соответствующий арбитражный суд кассационной инстанции в трехдневный срок со дня поступления жалобы в суд.","article_title":"Статья 275. Порядок подачи кассационной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6d782fe693200933bae8194736ea988b2f1c59115b5f080849c7b7b0c4ec74cf"},{"code_id":"APK_RF","article_number":"277","version_date":"2002-07-24","article_text":"1. Кассационная жалоба подается в арбитражный суд на бумажном носителе или в электронном виде, в том числе в форме электронного документа. Кассационная жалоба подписывается лицом, подающим жалобу, или его представителем, уполномоченным на подписание жалобы.\n\nКассационная жалоба, подаваемая в электронном виде, содержащая ходатайство об обеспечении иска, должна быть подписана усиленной квалифицированной электронной подписью.\n\n(Часть в редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В кассационной жалобе должны быть указаны:\n\n1) наименование арбитражного суда, в который подается кассационная жалоба;\n\n2) наименования лица, подающего жалобу, с указанием его процессуального положения, а также других лиц, участвующих в деле, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) наименование арбитражного суда, принявшего обжалуемое решение, постановление, номер дела и дата принятия решения, постановления, предмет спора;\n\n4) требования лица, подающего жалобу, о проверке законности обжалуемого судебного акта и основания, по которым лицо, подающее жалобу, обжалует решение, постановление, со ссылкой на законы или иные нормативные правовые акты, обстоятельства дела и имеющиеся в деле доказательства;\n\n5) перечень прилагаемых к жалобе документов.\n\nВ кассационной жалобе могут быть также указаны номера телефонов, факсов, адреса электронной почты и иные необходимые для рассмотрения дела сведения, заявлены имеющиеся ходатайства.\n\n3. Лицо, подающее кассационную жалобу, обязано направить другим лицам, участвующим в деле, копии кассационной жалобы и прилагаемых к ней документов, которые у них отсутствуют, заказным письмом с уведомлением о вручении либо вручить их другим участвующим в деле лицам или их представителям лично под расписку.\n\nКассационная жалоба и прилагаемые к ней документы в электронном виде направляются лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n4. К кассационной жалобе прилагаются:\n\n1) копия обжалуемого судебного акта;\n\n2) документы, подтверждающие уплату государственной пошлины в установленных порядке и размере или право на получение льготы по уплате государственной пошлины, либо ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины, об уменьшении ее размера;\n\n3) документы, подтверждающие направление или вручение другим лицам, участвующим в деле, копий кассационной жалобы и документов, которые у них отсутствуют;\n\n4) доверенность или иной документ, подтверждающие полномочия на подписание кассационной жалобы, а также копии документов о высшем юридическом образовании или об ученой степени по юридической специальности представителя, подписавшего кассационную жалобу, либо документов, удостоверяющих его статус адвоката, патентного поверенного, арбитражного управляющего, единоличного органа управления организации. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)","article_title":"Статья 277. Форма и содержание кассационной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"846dc2a0840f82e7b684961501592f769161e24a47dbc9b595de1a4c4a9476a0"},{"code_id":"APK_RF","article_number":"278","version_date":"2002-07-24","article_text":"1. Кассационная жалоба, поданная с соблюдением требований, предъявляемых настоящим Кодексом к ее форме и содержанию, принимается к производству арбитражного суда кассационной инстанции. В случае нарушения указанных требований арбитражный суд кассационной инстанции или оставляет кассационную жалобу без движения, или возвращает кассационную жалобу в порядке, предусмотренном статьями 280, 281 настоящего Кодекса.\n\n2. Вопрос о принятии кассационной жалобы к производству арбитражного суда кассационной инстанции решается судьей единолично в пятидневный срок со дня ее поступления в арбитражный суд кассационной инстанции.\n\n3. О принятии кассационной жалобы к производству арбитражный суд выносит определение, которым возбуждается производство по кассационной жалобе.\n\nВ определении указываются время и место проведения судебного заседания по рассмотрению кассационной жалобы. При этом время проведения первого судебного заседания по рассмотрению кассационной жалобы определяется с учетом того, что оно не может быть назначено ранее истечения срока, установленного настоящим Кодексом для подачи кассационной жалобы. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nКопии определения о принятии кассационной жалобы направляются лицам, участвующим в деле, не позднее следующего дня после дня его вынесения.","article_title":"Статья 278. Принятие кассационной жалобы к производству арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"db1b052ac750d31835e4be6025892a98c7bbecc5312ccb717634ad2472bdb06d"}]$law7d0014$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
